#include "s61_binary_deeper_cubic_field_20261101.hpp"
#include <chrono>
using namespace cubic_field;
struct Poly{fmpq_mpoly_t p;Poly(){fmpq_mpoly_init(p,ctx);}Poly(const Poly&a):Poly(){fmpq_mpoly_set(p,a.p,ctx);}Poly(Poly&&a):Poly(){fmpq_mpoly_swap(p,a.p,ctx);}Poly&operator=(Poly a){fmpq_mpoly_swap(p,a.p,ctx);return *this;}~Poly(){fmpq_mpoly_clear(p,ctx);}};
Fraction frac(const Poly&p){Fraction r;fmpq_mpoly_set(r.numerator,p.p,ctx);return r;}
void write(ostream&o,const Poly&a){fmpq_t q;fmpq_init(q);ulong ex[2];int n=fmpq_mpoly_length(a.p,ctx);o<<n;for(int i=0;i<n;i++){fmpq_mpoly_get_term_coeff_fmpq(q,a.p,i,ctx);fmpq_mpoly_get_term_exp_ui(ex,a.p,i,ctx);char*s=fmpq_get_str(nullptr,10,q);o<<' '<<s<<' '<<ex[0]<<' '<<ex[1];flint_free(s);}o<<'\n';fmpq_clear(q);}
int main(int argc,char**argv){assert(argc==6);fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream denin(argv[1]),pin(argv[2]),l0in(argv[3]),l1in(argv[4]);ofstream out(argv[5]);assert(denin&&pin&&l0in&&l1in&&out);int n,m;pin>>n>>m;assert(n==158&&m==75);vector<Fraction>P(158);for(int i=0;i<158;i++){read_poly(denin,P[i].numerator);read_poly(pin,P[i].denominator);if(fmpq_mpoly_is_zero(P[i].denominator,ctx))fmpq_mpoly_one(P[i].denominator,ctx);P[i].reduce();Poly tmp;for(int j=0;j<75;j++)read_poly(pin,tmp.p);}vector<vector<Poly>>L0(158,vector<Poly>(189));for(int i=0;i<42;i++)fmpq_mpoly_one(L0[i][i].p,ctx);for(int i=0;i<116;i++){string s;int j;l0in>>s>>j;assert(s=="KERNEL"&&j==i);Poly den;read_poly(l0in,den.p);for(int k=0;k<147;k++)read_poly(l0in,L0[i+42][k+42].p);}out<<117<<' '<<189<<'\n';auto start=chrono::steady_clock::now();long total=0;for(int j=0;j<117;j++){string s;int k;l1in>>s>>k;assert(s=="KERNEL"&&k==j);Poly den;read_poly(l1in,den.p);vector<Fraction>row(189);for(int i=0;i<158;i++){Poly v;read_poly(l1in,v.p);if(fmpq_mpoly_is_zero(v.p,ctx))continue;Fraction c=multiply(frac(v),P[i]);for(int h=0;h<189;h++)if(!fmpq_mpoly_is_zero(L0[i][h].p,ctx)){Fraction x=multiply(c,frac(L0[i][h]));fmpq_mpoly_neg(x.numerator,x.numerator,ctx);row[h]=subtract(row[h],x);}}Poly D,g,q,tmp;fmpq_mpoly_one(D.p,ctx);for(auto&x:row){assert(fmpq_mpoly_gcd(g.p,D.p,x.denominator,ctx));assert(fmpq_mpoly_divides(q.p,x.denominator,g.p,ctx));fmpq_mpoly_mul(tmp.p,D.p,q.p,ctx);D=tmp;}vector<Poly>num(189);fmpq_mpoly_zero(g.p,ctx);for(int h=0;h<189;h++){assert(fmpq_mpoly_divides(q.p,D.p,row[h].denominator,ctx));fmpq_mpoly_mul(num[h].p,row[h].numerator,q.p,ctx);assert(fmpq_mpoly_gcd(tmp.p,g.p,num[h].p,ctx));g=tmp;}assert(!fmpq_mpoly_is_zero(g.p,ctx));write(out,D);write(out,g);for(auto&x:num){assert(fmpq_mpoly_divides(q.p,x.p,g.p,ctx));x=q;total+=fmpq_mpoly_length(x.p,ctx);write(out,x);}out.flush();double sec=chrono::duration<double>(chrono::steady_clock::now()-start).count();if(j%10==0)cerr<<"LEFT_OP "<<j<<" TERMS "<<total<<" SEC "<<sec<<'\n';assert(total<4000000);}cerr<<"PASS TERMS "<<total<<'\n';}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
